window.kbPageData["views/entry/k-952cbd5333fa6f4b"] = {"key":"entry/k-952cbd5333fa6f4b","state":{"route":"entry/k-952cbd5333fa6f4b"},"node":{"id":"k-952cbd5333fa6f4b","mode":"k","title":"预付款消费的书面合同","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["经营者收取预付款提供商品或服务应与消费者订立书面合同"],"qs":["国考 2025 行政执法 行测#26"],"current":true,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"经营者以收取预付款的方式提供商品或者服务，应当与消费者订立书面合同，约定商品或者服务的具体内容、价款或者费用、预付款退还方式及违约责任等事项。","review":{"definition":"经营者以收取预付款的方式提供商品或者服务，应当与消费者订立书面合同，约定商品或者服务的具体内容、价款或者费用、预付款退还方式及违约责任等事项。","explanation":"D项中，健身馆预收3000元，用于购买随后半年的私教服务，适用预付款消费的书面合同要求。题干列出了书面合同约定的服务和费用，D项的做法符合题目考查的要求。若要判断合同条款是否齐备，还需看是否约定预付款退还方式和违约责任等事项。","references":[],"evidence":"丁健身馆与消费者签订书面合同，约定提供为期半年的健身私教课程服务并收取3000元预付款","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 行政执法 行测#26":{"paper":"国考 2025 行政执法 行测","n":26,"mod":"常识判断","src":["d8efe4e19862104d89c8.pdf",4],"asrc":["e2c4b1970d2b49eac0fd.pdf",9],"card":"1d5cddb0488cb8464afb5007","links":[{"id":"k-952cbd5333fa6f4b","role":"直接考查","why":"健身馆预收课程费用时，应签订书面合同约定服务内容、费用、退款方式和违约责任等事项。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-952cbd5333fa6f4b":[["国考 2025 行政执法 行测#26"]]}};
